// CreateTableWithDBType creates the Customer_Bank_Account table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *CustomerBankAccount) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, CustomerBankAccountTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetCustomerBankAccountPostgresTableSchema()
	} else {
		schema = GetCustomerBankAccountTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Customer_Bank_Account table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *CustomerBankAccount) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, CustomerBankAccountTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (customer_no, code)`,
		fmt.Sprintf("%s$Customer_Bank_Account$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range customerBankAccountSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, CustomerBankAccountTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, CustomerBankAccountTableName, keys)
}

// customerBankAccountSIFTSpecs are the table's keys with sum_index_fields
func customerBankAccountSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *CustomerBankAccount) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, CustomerBankAccountTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range customerBankAccountSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, CustomerBankAccountTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: CustomerBankAccountTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, CustomerBankAccountTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

